import React, { useState } from 'react';
import { Copy, Check, Sparkles, ArrowRight } from 'lucide-react';
import toast from 'react-hot-toast';

const RewriteCard = ({ rewrite }) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(rewrite.improved);
    setCopied(true);
    toast.success('Improved bullet copied!');
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="glass-card p-5 rounded-2xl border border-bronze-100/15 space-y-3 transition-all duration-300 hover:border-gold-300/40">

      {/* Original Bullet */}
      <div className="p-3 rounded-xl bg-bronze-950/70 border border-bronze-100/10 text-bronze-200 text-sm font-sans flex items-start space-x-2">
        <span className="px-2 py-0.5 rounded text-[10px] font-mono font-semibold bg-bronze-800 text-bronze-200 border border-bronze-100/20 uppercase shrink-0 mt-0.5">
          BEFORE
        </span>
        <p className="line-through leading-relaxed opacity-70">{rewrite.original}</p>
      </div>

      {/* Improved AI Bullet */}
      <div className="p-3.5 rounded-xl bg-gradient-to-r from-bronze-700/40 via-bronze-600/30 to-transparent border border-gold-300/40 text-bronze-100 font-medium text-sm flex items-start justify-between space-x-3 shadow-gold-glow">
        <div className="flex items-start space-x-2">
          <span className="px-2 py-0.5 rounded text-[10px] font-mono font-semibold bg-gold-300/20 text-gold-300 border border-gold-300/40 uppercase shrink-0 mt-0.5 flex items-center space-x-1">
            <Sparkles className="w-3 h-3 text-gold-300" />
            <span>AI REWRITE</span>
          </span>
          <p className="leading-relaxed text-bronze-100">{rewrite.improved}</p>
        </div>

        <button
          onClick={handleCopy}
          className="p-2 rounded-lg bg-gold-300/20 hover:bg-gold-300/30 text-gold-300 transition-all border border-gold-300/40 shrink-0"
          title="Copy bullet"
        >
          {copied ? <Check className="w-4 h-4 text-gold-300" /> : <Copy className="w-4 h-4" />}
        </button>
      </div>

      {/* AI Reasoning */}
      {rewrite.reason && (
        <div className="flex items-center space-x-2 text-xs font-mono text-gold-300/90 pt-1">
          <ArrowRight className="w-3.5 h-3.5 text-gold-300" />
          <span>Rationale: {rewrite.reason}</span>
        </div>
      )}
    </div>
  );
};

export default RewriteCard;
